import React from "react";

const EventList = ({ events }) => {
  return (
    <div>
      <h2>All Events</h2>
      {events.map((ev) => (
        <div key={ev._id} style={{ padding: "10px", border: "1px solid #ddd", marginBottom: "10px" }}>
          <h3>{ev.title}</h3>
          <p>{ev.description}</p>
          <p><b>Date:</b> {ev.date}</p>
          <p><b>Location:</b> {ev.location}</p>
        </div>
      ))}
    </div>
  );
};

export default EventList;
